import std.io

interface A1 {
    fn a(self) -> Int64
}
interface B1 {
    fn b(self) -> String
}
record P { n: Int64 }
impl A1 for P {
    fn a(self) -> Int64 {
        self.n
    }
}
impl B1 for P {
    fn b(self) -> String {
        "p"
    }
}
fn use2<T>(x: T) -> Int64 where T: A1 + B1 {
    x.a()
}
pub type AppError = Failed(String)
pub fn main() effect io -> Result<(), AppError> {
    let p = P { n: 1 }
    let n = use2(p)
    io.println("${n}")
    return Ok(())
}
